# Cache-aside strategy demonstration
import functools

_cache = {}

def get_from_db(key):
    # Simulates a slow database call
    db = {'user:1': 'Alice', 'user:2': 'Bob', 'user:3': 'Carol'}
    return db.get(key)

def get(key):
    if key in _cache:
        print(f'CACHE HIT  : {key} -> {_cache[key]}')
        return _cache[key]
    value = get_from_db(key)
    if value is not None:
        _cache[key] = value
        print(f'CACHE MISS : {key} -> {value}  (stored in cache)')
    return value

keys_to_fetch = ['user:1', 'user:2', 'user:1', 'user:3', 'user:2']
for k in keys_to_fetch:
    get(k)

hits = sum(1 for k in keys_to_fetch if k in _cache)
print(f'Cache size: {len(_cache)} entries')
